//autogenerated:yes
//nolint:revive,govet,errcheck
package asluav_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/asluav"
)

func TestEnum_GSM_MODEM_TYPE(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.GSM_MODEM_TYPE
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.GSM_MODEM_TYPE_UNKNOWN.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.GSM_MODEM_TYPE
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.GSM_MODEM_TYPE_UNKNOWN, dec)
	})
}
